import{z as i,x as p,o as r,c,q as n,j as l,D as o,d as a,s as E,S as d,b as t}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"挂载与 superblock","description":"","frontmatter":{"title":"挂载与 superblock","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/mount-super.md","filePath":"cs/mount-super.md","lastUpdated":1791063341000}'),B={name:"cs/mount-super.md"};function u(A,e,m,D,S,h){const s=p("Mermaid");return r(),c("div",null,[e[2]||(e[2]=n('<h1 id="挂载与-superblock" tabindex="-1">挂载与 superblock <a class="header-anchor" href="#挂载与-superblock" aria-label="Permalink to &quot;挂载与 superblock&quot;">​</a></h1><div class="epigraph"><p>超级块描述一次已挂载的文件系统实例；挂载点把该实例的根接到目录树的某个 dentry 上。</p><footer>—— 据 Kleiman 的 vnode；McKusick 对 BSD 挂载的整理；Linux VFS 文档</footer></div><p><a href="/cs/vfs">上一课</a>给出操作表，底下可以是不同 FS。<a href="/cs/path-lookup">路径查找</a>会碰到「换超级块」的接口。<a href="/cs/inode-dir">inode</a> 号只在一台已挂载实例内有意义。缺口是<strong>挂载</strong>：设备、类型、根 inode、选项，以及用户看见的单棵树如何由多棵拼成。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>若全局只有一棵磁盘上的树，U 盘与 NFS 无法接到 <code>/mnt</code>。若每个 FS 自己实现整条 <code>open</code> 路径，VFS 白做。缺口：<code>mount</code> 读设备上的超级块（魔数、块大小、根 inode），在内核创建 <code>super_block</code>，把某目录变成挂载点——lookup 走到该 dentry 时切换 super，从客 FS 的根继续。卸载要保证无忙 inode，并写回脏元数据。</p><p><span class="marginnote">魔数就是写在磁盘固定偏移上的一个「暗号」整数，用来回答「这块设备到底是哪种文件系统」。例如 ext2/ext4 的魔数是 0xEF53，挂在超级块的固定位置；<code>mount -t</code> 指定错了类型，读出的暗号对不上就会直接拒绝。</span></p><p>本课不把绑定挂载与命名空间的容器语义写完，那是隔离课。</p><p><span class="marginnote">同一设备可只读挂、可挂多次（实现相关）。proc、sysfs 没有块设备，超级块仍存在，只是内存里造出来。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><code>mount(source, target, fstype, flags, data)</code>：VFS 调该类型的 <code>fill_super</code>，建立根 dentry。后续 <a href="/cs/dcache">dcache</a> 在挂载点上有「越过」逻辑。<code>umount</code> 检查引用。根文件系统在启动时由 init 指定，后课 early-boot 再接。用户路径仍从进程 root 开始，不感知设备号。</p><p><span class="marginnote">可以把挂载想象成园艺嫁接：U 盘本来是一棵独立的树，<code>mount</code> 把它的根「接穗」到主树 <code>/mnt</code> 这个「砧木」位置上。接好之后用户只看见一棵树，走到嫁接点就自然滑到新枝上——路径查找完全感知不到接缝，卸载则是把接穗拆走，砧木上原目录又露出来。</span></p>',11)),(r(),l(d,null,{default:o(()=>[E(s,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20DEV%5B%22%E8%AE%BE%E5%A4%87%E6%88%96%E4%BC%AA%20FS%22%5D%20--%3E%20SB%5B%22super_block%22%5D%0A%20%20SB%20--%3E%20ROOT%5B%22%E8%AF%A5%E5%AE%9E%E4%BE%8B%E7%9A%84%E6%A0%B9%20dentry%22%5D%0A%20%20MNT%5B%22%E6%8C%82%E8%BD%BD%E7%82%B9%22%5D%20--%3E%20ROOT%0A%20%20LOOK%5B%22lookup%20%E9%81%87%E6%8C%82%E8%BD%BD%E7%82%B9%22%5D%20--%3E%20SB%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[a(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=t("h2",{id:"机制",tabindex:"-1"},[a("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),e[4]||(e[4]=t("p",null,[a("超级块把「哪一种 FS、哪一份数据」变成内核对象，VFS 操作表有了 "),t("code",null,"this"),a(" 指针。崩溃一致性后课要写回的正是这份 super 与其 inode。不要把挂载写成包管理器或容器镜像教程；对象只是树的拼接。块如何进内存，缓冲课已经在下一课等着。")],-1)),(r(),l(d,null,{default:o(()=>[E(s,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E9%80%90%E6%AE%B5%E8%A7%A3%E6%9E%90%20%2Fmnt%2Fusb%2Fa.txt%22%5D%20--%3E%20D1%5B%22%E8%B5%B0%E5%88%B0%20dentry%3A%20mnt%22%5D%0A%20%20D1%20--%3E%20MP%7B%22%E6%98%AF%E6%8C%82%E8%BD%BD%E7%82%B9%3F%22%7D%0A%20%20MP%20--%3E%7C%22%E5%90%A6%22%7C%20NEXT%5B%22%E7%BB%A7%E7%BB%AD%E5%9C%A8%E5%BD%93%E5%89%8D%20super%20%E9%87%8C%E6%89%BE%E4%B8%8B%E4%B8%80%E6%AE%B5%22%5D%0A%20%20MP%20--%3E%7C%22%E6%98%AF%22%7C%20CROSS%5B%22follow_mount%3A%20%E8%B6%8A%E5%88%B0%E5%AE%A2%20FS%20%E6%A0%B9%22%5D%0A%20%20CROSS%20--%3E%20NS%5B%22%E6%8D%A2%E6%88%90%20U%20%E7%9B%98%E7%9A%84%20super_block%22%5D%0A%20%20NS%20--%3E%20D2%5B%22%E4%BB%8E%E5%AE%A2%20FS%20%E6%A0%B9%E7%BB%A7%E7%BB%AD%E6%89%BE%20usb%22%5D%0A%20%20D2%20--%3E%20FIN%5B%22%E8%90%BD%E5%9C%A8%E5%AE%A2%20FS%20%E7%9A%84%20inode%3A%20%E6%89%93%E5%BC%80%22%5D%0A%20%20NEXT%20--%3E%20FIN2%5B%22%E8%90%BD%E5%9C%A8%E4%B8%BB%20FS%20%E7%9A%84%20inode%22%5D%0A"})]),fallback:o(()=>[...e[1]||(e[1]=[a(" Loading... ",-1)])]),_:1})),e[5]||(e[5]=n('<p><span class="marginnote">初学者容易以为 inode 号是全机唯一的编号。实际上它只在<strong>一份已挂载实例</strong>里有意义——U 盘上的 2 号 inode 和根文件系统的 2 号 inode 互不相干，内核区分对象靠（挂载实例, inode 号）这一对，单看号码会撞车。</span></p><p>与<a href="/cs/user-kernel-split">用户/内核分裂</a>无关：挂载是命名空间里的树，不是虚地址。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 loop 设备加密的全部栈。不保证所有 FS 支持在线 resize。下一课缓冲与脏页会假定：已有一块已挂载实例，读写落到块号。</p><p>后课默认：目录树可由多个 super 拼成。块在内存中的 Cache 与脏位，下一课缓冲与脏页。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>super_block 是一次挂载实例；挂载点切换查找。</li><li>伪文件系统同样有超级块，只是无磁盘。</li><li>脏缓冲与写回是下一课。</li><li>出处：Kleiman, 1986；McKusick et al., <em>4.4BSD</em>；Linux VFS。</li></ul>',7))])}const b=i(B,[["render",u]]);export{_ as __pageData,b as default};
